package com.bank.storage.lake;

import com.bank.storage.model.LakeRecord;
import java.util.*;
import java.util.logging.Logger;

// Cheap raw storage: accepts ANYTHING, keeps it all.
public class DataLake {
    private static final Logger log = Logger.getLogger(DataLake.class.getName());
    private final List<LakeRecord> storage = new ArrayList<>();

    public void dump(LakeRecord record) {
        storage.add(record); // no validation — raw zone
        log.fine(() -> "LAKE dumped raw record " + record.getRawId());
    }
    public List<LakeRecord> readAll() { return storage; }
    public int size() { return storage.size(); }
}
