package com.bank.storage.warehouse;

import com.bank.storage.model.WarehouseRow;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Structured analytical store: only conformed rows; fast aggregates.
public class DataWarehouse {
    private static final Logger log = Logger.getLogger(DataWarehouse.class.getName());
    private final List<WarehouseRow> rows = new ArrayList<>();

    public void insert(WarehouseRow row) {
        rows.add(row);
        log.fine(() -> "WAREHOUSE inserted conformed row " + row.getTxnId());
    }

    // OLAP-style aggregate query.
    public Map<String, BigDecimal> totalByAccount() {
        Map<String, BigDecimal> totals = new LinkedHashMap<>();
        for (WarehouseRow r : rows) {
            totals.merge(r.getAccountId(), r.getAmount(), BigDecimal::add);
        }
        return totals;
    }
    public int size() { return rows.size(); }
}
