package com.bank.storage.curation;

import com.bank.storage.lake.DataLake;
import com.bank.storage.model.*;
import com.bank.storage.warehouse.DataWarehouse;
import java.math.BigDecimal;
import java.util.logging.Logger;

// Promotes raw lake data into the curated warehouse (lake-to-warehouse ETL).
public class Curation {
    private static final Logger log = Logger.getLogger(Curation.class.getName());

    public void promote(DataLake lake, DataWarehouse warehouse) {
        log.info("CURATION: promoting valid lake records into the warehouse");
        for (LakeRecord r : lake.readAll()) {
            if (r.getAmount() == null || r.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
                log.warning(() -> "Skipping invalid lake record " + r.getRawId());
                continue;
            }
            warehouse.insert(new WarehouseRow(r.getRawId(), r.getAccountId(), r.getAmount()));
        }
    }
}
