package com.bank.storage;

import com.bank.storage.curation.Curation;
import com.bank.storage.lake.DataLake;
import com.bank.storage.model.LakeRecord;
import com.bank.storage.warehouse.DataWarehouse;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class StorageDemo {
    private static final Logger log = Logger.getLogger(StorageDemo.class.getName());

    public static void main(String[] args) {
        DataLake lake = new DataLake();
        DataWarehouse warehouse = new DataWarehouse();

        lake.dump(new LakeRecord("R1", "SAV2001", new BigDecimal("1200.00")));
        lake.dump(new LakeRecord("R2", "SAV2001", new BigDecimal("800.00")));
        lake.dump(new LakeRecord("R3", "CUR3001", new BigDecimal("5000.00")));
        lake.dump(new LakeRecord("R4", "CUR3001", null)); // raw junk kept in lake

        log.info("Lake holds " + lake.size() + " raw records (including junk)");

        new Curation().promote(lake, warehouse);
        log.info("Warehouse holds " + warehouse.size() + " curated rows");

        log.info("=== FAST OLAP QUERY: total by account ===");
        warehouse.totalByAccount().forEach((acc, total) ->
            log.info(acc + " = " + total));
    }
}
